textOptions.schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "chat_id",
    "search_query",
    "experience",
    "schedule",
    "location"
  ],
  "properties": {
    "chat_id": {
      "type": "integer",
      "description": "Telegram chat ID of the user"
    },
    "search_query": {
      "type": "string",
      "description": "Keyword-based resume search query for hh.kz"
    },
    "experience": {
      "type": "string",
      "enum": [
        "noExperience",
        "between1And3",
        "between3And6",
        "moreThan6"
      ],
      "description": "Work experience filter according to hh.kz"
    },
    "schedule": {
      "type": "string",
      "enum": [
        "fullDay",
        "shift",
        "flexible",
        "remote"
      ],
      "description": "Work schedule or employment type"
    },
    "location": {
      "type": "string",
      "description": "Country or region for resume search"
    }
  }
}
